package com.justenoughmods.achievementguide.integration.battlearmor;
import com.justenoughmods.achievementguide.integration.battle.*;import com.github.L_Ender.lionfishapi.server.event.StandOnFluidEvent;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerPlayer;import net.minecraft.tags.FluidTags;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.VoxelShape;import net.minecraft.core.Direction;
public final class WorldBattleArmorQuestMotion {
 public static final class Move {public final ServerPlayer actor;public final Vec3 start;public final ItemStack boots;public boolean sturdy,lava,vanillaSnowFalse,finalSnow;public final List<BlockPos> snow=new ArrayList<>();public Move(ServerPlayer actor){this.actor=actor;start=actor.position();boots=actor.getItemBySlot(EquipmentSlot.FEET).copy();}}
 public static final class Packet {public final ServerPlayer actor;public final Vec3 start;public Move lava,snow,flight;public Packet(ServerPlayer actor){this.actor=actor;start=actor.position();}}
 public record Fluid(Move move,ItemStack boots,boolean uncanceled,boolean committed){}
 public record Launch(ServerPlayer actor,ItemStack boots,Vec3 velocity,Vec3 start,boolean cooldown,boolean grounded){}
 public record Pending(String dimension,long time,Vec3 start,Vec3 impulse,ItemStack stack){}
 private static final ThreadLocal<ArrayDeque<Move>> MOVES=ThreadLocal.withInitial(ArrayDeque::new);
 private static final ThreadLocal<ArrayDeque<Packet>> PACKETS=ThreadLocal.withInitial(ArrayDeque::new);
 private static final Map<StandOnFluidEvent,Fluid> FLUIDS=new IdentityHashMap<>();private static final Map<UUID,Pending> STEPS=new LinkedHashMap<>(),FLIGHTS=new LinkedHashMap<>();private static final int LIMIT=1024;
 public static Move begin(Entity entity){var actor=WorldBattleArmorQuestProof.real(entity);if(actor==null||MOVES.get().size()>=16)return null;var move=new Move(actor);MOVES.get().push(move);return move;}
 public static Move current(Entity entity){for(var move:MOVES.get())if(move.actor==entity)return move;return null;}
 public static void fluidBefore(StandOnFluidEvent event){if(!(event.getEntity().level() instanceof net.minecraft.server.level.ServerLevel))return;var move=current(event.getEntity());if(move!=null&&FLUIDS.size()<256&&event.getFluidState().is(FluidTags.LAVA)&&!event.getEntity().isShiftKeyDown()&&WorldBattleArmorQuestProof.smith(move.actor,EquipmentSlot.FEET,"ignitium","ignitium_boots"))FLUIDS.put(event,new Fluid(move,move.actor.getItemBySlot(EquipmentSlot.FEET).copy(),!event.isCanceled(),false));}
 public static void fluidNative(StandOnFluidEvent event,boolean canceledBefore){if(!(event.getEntity().level() instanceof net.minecraft.server.level.ServerLevel))return;var r=FLUIDS.get(event);if(r!=null&&r.uncanceled&&!canceledBefore&&event.isCanceled())FLUIDS.put(event,new Fluid(r.move,r.boots,r.uncanceled,true));}
 public static void fluidAfter(StandOnFluidEvent event){if(!(event.getEntity().level() instanceof net.minecraft.server.level.ServerLevel))return;var receipt=FLUIDS.get(event);if(receipt!=null&&(!receipt.uncanceled||!receipt.committed||!event.isCanceled()))FLUIDS.remove(event);}
 public static void posted(StandOnFluidEvent event){if(!(event.getEntity().level() instanceof net.minecraft.server.level.ServerLevel))return;var receipt=FLUIDS.remove(event);if(receipt!=null&&receipt.uncanceled&&receipt.committed&&event.isCanceled()&&current(event.getEntity())==receipt.move&&WorldBattleArmorQuestProof.same(receipt.boots,receipt.move.actor.getItemBySlot(EquipmentSlot.FEET)))receipt.move.lava=true;}
 public static void sturdy(Entity entity,ItemStack stack,boolean accepted){var move=current(entity);if(move!=null&&accepted&&BattleQuestProof.item(stack).equals("cataclysm:sturdy_boots")&&!move.actor.getItemBySlot(EquipmentSlot.FEET).is(Items.LEATHER_BOOTS))move.sturdy=true;}
 public static void snowBaseline(Entity entity,boolean vanilla){var move=current(entity);if(move!=null){move.vanillaSnowFalse=!vanilla;move.finalSnow=false;move.sturdy=false;}}
 public static void snowFinal(Entity entity,boolean accepted){var move=current(entity);if(move!=null)move.finalSnow=accepted&&move.vanillaSnowFalse&&move.sturdy;}
 public static void snowShape(Entity entity,BlockPos pos,VoxelShape shape){var move=current(entity);if(move!=null&&move.sturdy&&move.finalSnow&&!shape.isEmpty()&&shape.max(Direction.Axis.Y)>=0.999&&move.snow.size()<32)move.snow.add(pos.immutable());}
 private static boolean onTop(ServerPlayer actor,BlockPos pos,double height){var box=actor.getBoundingBox();return Math.abs(box.minY-(pos.getY()+height))<=0.035&&box.maxX>pos.getX()+0.0001&&box.minX<pos.getX()+1-0.0001&&box.maxZ>pos.getZ()+0.0001&&box.minZ<pos.getZ()+1-0.0001;}
 private static boolean lavaTop(ServerPlayer actor){var box=actor.getBoundingBox();int y=(int)Math.floor(box.minY-0.02);for(int x=(int)Math.floor(box.minX);x<=Math.floor(box.maxX-0.0001);x++)for(int z=(int)Math.floor(box.minZ);z<=Math.floor(box.maxZ-0.0001);z++){var pos=new BlockPos(x,y,z);var fluid=actor.level().getFluidState(pos);if(fluid.is(FluidTags.LAVA)&&onTop(actor,pos,fluid.getHeight(actor.level(),pos)))return true;}return false;}
 public static void end(Move move){if(move==null)return;var q=MOVES.get();q.removeFirstOccurrence(move);if(q.isEmpty())MOVES.remove();var actor=move.actor;if(WorldBattleArmorQuestProof.real(actor)==null)return;double horizontal=actor.position().subtract(move.start).horizontalDistanceSqr();if(horizontal>0.000001&&actor.onGround()){
  if(move.lava&&WorldBattleArmorQuestProof.same(move.boots,actor.getItemBySlot(EquipmentSlot.FEET))&&WorldBattleArmorQuestProof.smith(actor,EquipmentSlot.FEET,"ignitium","ignitium_boots")&&lavaTop(actor))award(move,"lava");
  if(move.sturdy&&com.github.L_Ender.cataclysm.util.EntityUtil.isEquipped(com.github.L_Ender.cataclysm.init.ModItems.STURDY_BOOTS.get(),actor))for(var pos:move.snow)if(actor.level().getBlockState(pos).is(Blocks.POWDER_SNOW)&&onTop(actor,pos,1.0)){award(move,"snow");break;}
 }
 var flight=FLIGHTS.get(actor.getUUID());if(flight!=null){long age=actor.level().getGameTime()-flight.time;if(age<0||age>2||!flight.dimension.equals(actor.level().dimension().location().toString())||!WorldBattleArmorQuestProof.same(flight.stack,actor.getItemBySlot(EquipmentSlot.CHEST))){FLIGHTS.remove(actor.getUUID());}else if(actor.isFallFlying()&&actor.position().distanceToSqr(move.start)>0.000001&&WorldBattleEquipmentOrigins.has(actor,actor.getItemBySlot(EquipmentSlot.CHEST),"battle_armor_elytra")){FLIGHTS.remove(actor.getUUID());award(move,"flight");}}
 }
 private static void award(Move move,String route){for(var packet:PACKETS.get())if(packet.actor==move.actor){switch(route){case "lava"->packet.lava=move;case "snow"->packet.snow=move;case "flight"->packet.flight=move;}return;}WorldBattleArmorQuestProof.emit(move.actor,route.equals("snow")?"v3_combat_abyss_kit":"v3_combat_forged_armor");}
 public static Packet packetBegin(ServerPlayer actor){if(WorldBattleArmorQuestProof.real(actor)==null||PACKETS.get().size()>=16)return null;var packet=new Packet(actor);PACKETS.get().push(packet);return packet;}
 public static void packetEnd(Packet packet,boolean accepted){if(packet==null)return;var q=PACKETS.get();q.removeFirstOccurrence(packet);if(q.isEmpty())PACKETS.remove();var actor=packet.actor;if(!accepted||WorldBattleArmorQuestProof.real(actor)==null||actor.position().distanceToSqr(packet.start)<=0.000001)return;
  if(packet.lava!=null&&actor.onGround()&&lavaTop(actor)&&WorldBattleArmorQuestProof.same(packet.lava.boots,actor.getItemBySlot(EquipmentSlot.FEET))&&WorldBattleArmorQuestProof.smith(actor,EquipmentSlot.FEET,"ignitium","ignitium_boots"))WorldBattleArmorQuestProof.emit(actor,"v3_combat_forged_armor");
  if(packet.snow!=null&&actor.onGround()&&com.github.L_Ender.cataclysm.util.EntityUtil.isEquipped(com.github.L_Ender.cataclysm.init.ModItems.STURDY_BOOTS.get(),actor))for(var pos:packet.snow.snow)if(actor.level().getBlockState(pos).is(Blocks.POWDER_SNOW)&&onTop(actor,pos,1.0)){WorldBattleArmorQuestProof.emit(actor,"v3_combat_abyss_kit");break;}
  if(packet.flight!=null&&actor.isFallFlying()&&WorldBattleEquipmentOrigins.has(actor,actor.getItemBySlot(EquipmentSlot.CHEST),"battle_armor_elytra"))WorldBattleArmorQuestProof.emit(actor,"v3_combat_forged_armor");
 }
 public static Launch launchBefore(ServerPlayer actor,ItemStack stack,int type){if(type!=7||WorldBattleArmorQuestProof.real(actor)==null)return null;STEPS.remove(actor.getUUID());return new Launch(actor,stack.copy(),actor.getDeltaMovement(),actor.position(),actor.getCooldowns().isOnCooldown(stack.getItem()),actor.onGround());}
 public static void launchAfter(Launch launch,ItemStack actual){if(launch==null)return;var actor=launch.actor;var impulse=actor.getDeltaMovement().subtract(launch.velocity);if(!launch.cooldown&&launch.grounded&&actor.getCooldowns().isOnCooldown(actual.getItem())&&impulse.horizontalDistanceSqr()>1.0&&actor.getDeltaMovement().y>0&&WorldBattleArmorQuestProof.same(launch.boots,actual)&&actor.getItemBySlot(EquipmentSlot.FEET)==actual&&WorldBattleArmorQuestProof.smith(actor,EquipmentSlot.FEET,"cursium","cursium_boots")&&STEPS.size()<LIMIT)STEPS.put(actor.getUUID(),new Pending(actor.level().dimension().location().toString(),actor.level().getGameTime(),launch.start,impulse,actual.copy()));}
 public static void acceptedMove(ServerPlayer actor,Vec3 before,Vec3 velocity,boolean accepted){var pending=STEPS.get(actor.getUUID());if(pending==null)return;long age=actor.level().getGameTime()-pending.time;if(WorldBattleArmorQuestProof.real(actor)==null||age<0||age>6||!pending.dimension.equals(actor.level().dimension().location().toString())||!WorldBattleArmorQuestProof.same(pending.stack,actor.getItemBySlot(EquipmentSlot.FEET))){STEPS.remove(actor.getUUID());return;}var moved=actor.position().subtract(before);double dot=moved.x*pending.impulse.x+moved.z*pending.impulse.z;double momentum=velocity.x*pending.impulse.x+velocity.z*pending.impulse.z;if(accepted&&dot>0.04&&momentum>0&&WorldBattleArmorQuestProof.smith(actor,EquipmentSlot.FEET,"cursium","cursium_boots")){STEPS.remove(actor.getUUID());WorldBattleArmorQuestProof.emit(actor,"v3_combat_cursium");}}
 public static void flight(ServerPlayer actor,ItemStack stack,boolean accepted){if(accepted&&actor.isFallFlying()&&actor.getItemBySlot(EquipmentSlot.CHEST)==stack&&WorldBattleEquipmentOrigins.has(actor,stack,"battle_armor_elytra")&&FLIGHTS.size()<LIMIT)FLIGHTS.put(actor.getUUID(),new Pending(actor.level().dimension().location().toString(),actor.level().getGameTime(),actor.position(),Vec3.ZERO,stack.copy()));}
 public static void clear(UUID actor){STEPS.remove(actor);FLIGHTS.remove(actor);FLUIDS.entrySet().removeIf(e->e.getValue().move.actor.getUUID().equals(actor));}
 public static void clear(){MOVES.remove();PACKETS.remove();FLUIDS.clear();STEPS.clear();FLIGHTS.clear();}
}
